import os, json, urllib.parse, urllib.request
url=os.environ['GALAXY_URL'].rstrip('/')
key=open(os.environ['GALAXY_API_KEY_FILE']).read().strip()
tool_id='toolshed.g2.bx.psu.edu/repos/devteam/gffread/gffread/2.2.1.4+galaxy0'
api=f'{url}/api/tools/{urllib.parse.quote(tool_id, safe=\"\")}?io_details=true'
req=urllib.request.Request(api, headers={'x-api-key':key})
with urllib.request.urlopen(req, timeout=60) as r:
    data=json.load(r)
# find inputs with options
def walk(o,path=''):
    if isinstance(o, dict):
        if 'options' in o:
            for opt in o['options']:
                if any(s in (opt.get('value') or '') + ' ' + (opt.get('label') or '') for s in ['GRCm39','mm39','Mus_musculus','Mouse']):
                    print(path, opt)
        for k,v in o.items():
            walk(v, path+'|'+str(k))
    elif isinstance(o, list):
        for i,v in enumerate(o):
            walk(v, path+f'[{i}]')
walk(data)
PY"

